create table sys_resource
(
    id            bigint auto_increment comment '主键ID'
        primary key,
    parent_id     bigint   default 0                 null comment '父级ID（0=根节点/一级菜单）',
    resource_name varchar(64)                        not null comment '资源名称',
    resource_code varchar(64)                        not null comment '资源编码（唯一标识，如：system:org）',
    resource_type tinyint                            not null comment '资源类型（1=一级菜单，2=二级菜单，3=按钮）',
    icon          varchar(128)                       null comment '菜单图标',
    path          varchar(256)                       null comment '路由路径（按钮类型可为空）',
    component     varchar(256)                       null comment '组件路径（按钮类型可为空）',
    redirect      varchar(256)                       null comment '重定向路径（可选）',
    sort          int      default 0                 null comment '排序（同级内升序）',
    visible       tinyint  default 1                 null comment '显示状态（0=隐藏，1=显示）',
    status        tinyint  default 1                 null comment '状态（0=禁用，1=正常）',
    remark        varchar(512)                       null comment '备注说明',
    create_time   datetime default CURRENT_TIMESTAMP null comment '创建时间',
    update_time   datetime default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '更新时间',
    create_by     bigint                             null comment '创建人ID',
    update_by     bigint                             null comment '更新人ID',
    is_deleted    tinyint  default 0                 null comment '是否删除（0=否，1=是）',
    constraint uk_resource_code
        unique (((case when (`is_deleted` = 0) then `resource_code` else NULL end)))
)
    comment '资源表' collate = utf8mb4_unicode_ci;

create index idx_resource_parent_id
    on sys_resource (parent_id);

create index idx_resource_status
    on sys_resource (status);

create index idx_resource_type
    on sys_resource (resource_type);

